    obtain ⟨n, hn, hx⟩ := hx;
    simp [Formula.complexity] at hn;
    have : n + 1 ≤ φ.complexity - ψ.complexity := by
      have : ψ.complexity + 1 ≤ φ.complexity := by simpa using complexity_lower hq;
      omega;
